CARDIO.register({"item":"d168","meta":{"num":"d168","label":"168","spe":"dermato","short":"Herpès, varicelle, zona","title":"Infections à herpès virus du sujet immunocompétent","section":"D","chapter":10,"pages":"209-240","sdd":[{"num":37,"label":"Éruptions chez l'enfant"},{"num":52,"label":"Odynophagie / dysphagie"},{"num":91,"label":"Anomalies des muqueuses"},{"num":93,"label":"Vésicules, éruption vésiculeuse (cutanéo-muqueuse)"},{"num":151,"label":"Œdème de la face et du cou"},{"num":305,"label":"Dépistage et conseils devant une infection sexuellement transmissible"},{"num":322,"label":"Vaccinations de l'adulte et de l'enfant"}]},"objectives":[{"id":"d168-obj-01","rank":"A","rubric":"Prévalence, épidémiologie","title":"Connaître les modes de transmission pour HSV et VZV","desc":""},{"id":"d168-obj-02","rank":"B","rubric":"Prévalence, épidémiologie","title":"Connaître les principales données épidémiologiques des infections à HSV et VZV","desc":"Fréquence, contagiosité, âges de survenue"},{"id":"d168-obj-03","rank":"B","rubric":"Éléments physiopathologiques","title":"Connaître les principales caractéristiques virales et la réponse immunitaire aux infections à herpès virus","desc":"Enveloppé à ADN"},{"id":"d168-obj-04","rank":"A","rubric":"Éléments physiopathologiques","title":"Connaître les différentes phases cliniques d'infection des Herpesviridae","desc":"Primo-infection, latence, réactivation"},{"id":"d168-obj-05","rank":"A","rubric":"Diagnostic positif","title":"Reconnaître une primo-infection et une récurrence à HSV1 et 2","desc":""},{"id":"d168-obj-06","rank":"B","rubric":"Diagnostic positif","title":"Connaître les facteurs favorisants des récurrences herpétiques","desc":""},{"id":"d168-obj-07","rank":"A","rubric":"Diagnostic positif","title":"Reconnaître une varicelle et ses principales complications","desc":""},{"id":"d168-obj-08","rank":"A","rubric":"Diagnostic positif","title":"Reconnaître un zona","desc":""},{"id":"d168-obj-09","rank":"A","rubric":"Diagnostic positif","title":"Reconnaître les principales complications du zona (kératite, douleurs post-zostériennes, neurologiques)","desc":""},{"id":"d168-obj-10","rank":"A","rubric":"Contenu multimédia","title":"Lésions de varicelle","desc":""},{"id":"d168-obj-11","rank":"A","rubric":"Contenu multimédia","title":"Primo-infection génitale HSV","desc":""},{"id":"d168-obj-12","rank":"A","rubric":"Contenu multimédia","title":"Herpès labial","desc":""},{"id":"d168-obj-13","rank":"A","rubric":"Contenu multimédia","title":"Zona thoracique ; zona du visage","desc":""},{"id":"d168-obj-14","rank":"B","rubric":"Examens complémentaires","title":"Connaître l'indication des PCR virales dans le diagnostic des infections à Herpesviridae","desc":""},{"id":"d168-obj-15","rank":"A","rubric":"Prise en charge","title":"Connaître les principes du traitement d'une infection à HSV et à VZV","desc":""},{"id":"d168-obj-16","rank":"B","rubric":"Prise en charge","title":"Connaître les principes de la prise en charge des manifestations ophtalmologiques d'un HSV","desc":""},{"id":"d168-obj-17","rank":"B","rubric":"Prise en charge","title":"Connaître les principales toxicités des traitements actifs sur HSV et VZV","desc":""},{"id":"d168-obj-18","rank":"B","rubric":"Prise en charge","title":"Connaître les indications du vaccin varicelle et du vaccin zona","desc":""}],"course":{"sections":[],"essentials":[],"numbers":[],"mnemonics":[]},"questions":[{"id":"d168-qroc-001","type":"QROC","rank":"A","objective":"d168-obj-05","tags":["définition"],"difficulty":1,"question":"Quel type d'herpès simplex virus infecte de façon préférentielle la région génitale ?","answer":"HSV2","accept":["HSV2","HSV 2","herpès simplex virus 2","herpes simplex virus de type 2"],"keywords":["hsv2"],"explanation":"HSV2 infecte préférentiellement la région génitale (IST, infection néonatale par la filière génitale), alors que HSV1 touche surtout la partie supérieure du corps. HSV1 est toutefois de plus en plus retrouvé dans les infections génitales (environ 50 % des primo-infections).","src":"p. 210"},{"id":"d168-qroc-002","type":"QROC","rank":"A","objective":"d168-obj-01","tags":["physiopathologie","grossesse"],"difficulty":2,"question":"Quels sont les trois temps possibles de la contamination maternofœtale par le virus herpès simplex ?","answer":"In utero, accouchement (filière génitale), période postnatale","accept":["in utero, accouchement et postnatal","in utero, à l'accouchement et après la naissance"],"keywords":["utero","accouch","post"],"explanation":"La contamination peut se faire in utero par voie transplacentaire, pendant l'accouchement par passage dans la filière génitale contaminante, ou après la naissance (mère ou entourage contaminant, contact direct).","src":"p. 211"},{"id":"d168-qroc-003","type":"QROC","rank":"A","objective":"d168-obj-04","tags":["clinique","épidémiologie"],"difficulty":1,"question":"Quelle proportion des primo-infections par HSV est asymptomatique ?","answer":"80 % (formes inapparentes, les plus fréquentes)","accept":["80","80 pour cent","quatre sur cinq"],"keywords":["80"],"explanation":"La primo-infection herpétique est asymptomatique dans 80 % des cas et symptomatique dans 20 % seulement. Le même partage s'observe pour les réactivations.","src":"p. 211, 214"},{"id":"d168-qroc-004","type":"QROC","rank":"A","objective":"d168-obj-04","tags":["définition"],"difficulty":2,"question":"Comment nomme-t-on le premier contact d'un patient déjà infecté par HSV1 avec le virus HSV2 ?","answer":"Une infection initiale non primaire","accept":["infection initiale non primaire","initiale non primaire","non primaire"],"keywords":["non primaire"],"explanation":"Il s'agit du premier contact infectant avec un type d'HSV chez un sujet déjà infecté par l'autre type. L'infection préalable ne protège pas, mais les signes cliniques sont généralement moins sévères.","src":"p. 212"},{"id":"d168-qroc-005","type":"QROC","rank":"A","objective":"d168-obj-05","tags":["clinique"],"difficulty":2,"question":"Sur les muqueuses, les vésicules herpétiques sont fugaces : quelles lésions observe-t-on et quel est leur contour caractéristique ?","answer":"Des érosions coalescentes à contours polycycliques","accept":["érosions polycycliques","érosions à contours polycycliques","contours polycycliques","polycycliques"],"keywords":["érosion","polycycl"],"explanation":"Les vésicules des muqueuses se rompent très vite : on voit des érosions arrondies ou ovalaires post-vésiculeuses, coalescentes, à contours polycycliques et à bords inflammatoires.","src":"p. 214"},{"id":"d168-qroc-006","type":"QROC","rank":"A","objective":"d168-obj-05","tags":["clinique","pédiatrie"],"difficulty":1,"question":"À partir de quel âge survient le plus souvent la gingivostomatite herpétique aiguë, et pour quelle raison ?","answer":"Après 6 mois, à la disparition des anticorps maternels protecteurs","accept":["6 mois","après 6 mois","plus de 6 mois"],"keywords":["6 mois","maternel"],"explanation":"La primo-infection buccale (HSV1 plus souvent que HSV2) touche surtout le petit enfant de plus de 6 mois, quand les anticorps protecteurs d'origine maternelle ont disparu.","src":"p. 214"},{"id":"d168-qroc-007","type":"QROC","rank":"A","objective":"d168-obj-05","tags":["clinique","pièges"],"difficulty":2,"question":"Quel signe fonctionnel traduit la gravité d'une gingivostomatite herpétique aiguë ?","answer":"Une alimentation impossible (dysphagie intense)","accept":["alimentation impossible","impossibilité de s'alimenter","dysphagie intense","dysphagie majeure"],"keywords":["aliment"],"explanation":"La dysphagie est intense et l'alimentation devient impossible : c'est un signe de gravité. Le tableau comprend aussi une fièvre à 39 °C, une haleine fétide et des adénopathies cervicales sensibles.","src":"p. 215"},{"id":"d168-qroc-008","type":"QROC","rank":"A","objective":"d168-obj-05","tags":["diagnostic","pièges"],"difficulty":2,"question":"Quel diagnostic différentiel d'une stomatite érosive aiguë se distingue de la gingivostomatite herpétique par l'absence de fièvre, de signes généraux et d'adénopathies ?","answer":"L'aphtose","accept":["aphtose","aphtes","aphte"],"keywords":["aph"],"explanation":"L'aphtose ne s'accompagne ni de fièvre ni d'adénopathies. Les autres diagnostics différentiels sont l'érythème polymorphe ou le syndrome de Stevens-Johnson (plusieurs muqueuses et signes cutanés) et l'herpangine (virus coxsackie).","src":"p. 215"},{"id":"d168-qroc-009","type":"QROC","rank":"A","objective":"d168-obj-11","tags":["clinique"],"difficulty":1,"question":"Quelle est la présentation typique de la primo-infection herpétique génitale chez la femme ?","answer":"Une vulvovaginite aiguë brutale, fébrile et très douloureuse","accept":["vulvovaginite aiguë","vulvovaginite herpétique","vulvovaginite"],"keywords":["vulvovaginite"],"explanation":"Vulvovaginite aiguë brutale avec malaise, fièvre et douleurs très intenses : muqueuse tuméfiée, érosions arrondies polycycliques (vésicules éphémères, souvent absentes) et adénopathies inguinales sensibles. L'évolution est favorable en 2 à 3 semaines.","src":"p. 215-216"},{"id":"d168-qroc-010","type":"QROC","rank":"A","objective":"d168-obj-11","tags":["complications","urgence"],"difficulty":2,"question":"Quelle complication urinaire, liée à la douleur, est un signe de gravité de la primo-infection herpétique génitale ?","answer":"La rétention urinaire","accept":["rétention urinaire","rétention d'urines","rétention d'urine"],"keywords":["rétention"],"explanation":"La rétention urinaire réactionnelle est un signe de gravité. Elle fait partie des formes sévères qui relèvent de l'aciclovir IV, avec sondage urinaire et antalgiques.","src":"p. 216, 225"},{"id":"d168-qroc-011","type":"QROC","rank":"A","objective":"d168-obj-11","tags":["diagnostic","pièges"],"difficulty":2,"question":"Une vulvite caustique ou traumatique est un diagnostic différentiel de la vulvovaginite herpétique : quel contexte faut-il savoir évoquer ?","answer":"Une maltraitance","accept":["maltraitance","une maltraitance"],"keywords":["maltraitance"],"explanation":"Devant une vulvite caustique ou traumatique, il faut savoir évoquer une maltraitance. L'autre diagnostic différentiel de la vulvovaginite herpétique est la vulvovaginite infectieuse non herpétique.","src":"p. 216"},{"id":"d168-qroc-012","type":"QROC","rank":"A","objective":"d168-obj-16","tags":["complications","pièges"],"difficulty":2,"question":"Quel traitement local favorise les ulcérations de cornée et les séquelles visuelles dans l'herpès oculaire ?","answer":"La corticothérapie locale","accept":["corticothérapie locale","corticoïdes locaux","corticoïde local"],"keywords":["cortico"],"explanation":"L'herpès oculaire (kérato-conjonctivite ou kératite aiguë unilatérale) expose à l'uvéite et aux ulcérations de cornée, favorisées par la corticothérapie locale. Un avis ophtalmologique est indispensable.","src":"p. 217"},{"id":"d168-qroc-013","type":"QROC","rank":"A","objective":"d168-obj-05","tags":["clinique","pédiatrie"],"difficulty":1,"question":"Comment nomme-t-on la surinfection herpétique d'une dermatite atopique, éruption vésiculeuse profuse et fébrile du sujet jeune ou du nourrisson ?","answer":"Le syndrome de Kaposi-Juliusberg","accept":["Kaposi-Juliusberg","Kaposi Juliusberg","syndrome de Kaposi-Juliusberg"],"keywords":["juliusberg"],"explanation":"Le syndrome de Kaposi-Juliusberg survient chez un atopique sévère ou en poussée : fièvre, altération de l'état général, éruption vésiculeuse, érosive et croûteuse à extension rapide, avec vésicules hémorragiques, pustules et ombilication centrale, débutant au visage.","src":"p. 217-218"},{"id":"d168-qroc-014","type":"QROC","rank":"A","objective":"d168-obj-15","tags":["traitement"],"difficulty":2,"question":"Quel traitement, et par quelle voie, est nécessaire devant un syndrome de Kaposi-Juliusberg ?","answer":"Un antiviral (aciclovir) par voie IV","accept":["aciclovir IV","antiviral IV","traitement antiviral IV","aciclovir par voie intraveineuse","antiviral par voie IV"],"keywords":["iv"],"explanation":"L'évolution est favorable en quelques jours sous traitement antiviral IV. D'une façon générale, toute forme grave d'herpès relève d'un traitement IV.","src":"p. 218, 226"},{"id":"d168-qroc-015","type":"QROC","rank":"A","objective":"d168-obj-05","tags":["grossesse","complications"],"difficulty":2,"question":"Quel risque maternel est accru lors d'une primo-infection herpétique survenant pendant la grossesse ?","answer":"Hépatite fulminante ou encéphalite","accept":["hépatite fulminante","encéphalite","hépatite fulminante ou encéphalite"],"keywords":["hépatite","encéphalite"],"explanation":"La primo-infection pendant la grossesse expose à un risque accru d'hépatite fulminante ou d'encéphalite. Les récurrences, fréquentes, exposent surtout au risque de transmission maternofœtale.","src":"p. 218"},{"id":"d168-qroc-016","type":"QROC","rank":"A","objective":"d168-obj-05","tags":["clinique","pédiatrie"],"difficulty":2,"question":"Quelles sont les trois formes cliniques de l'herpès néonatal ?","answer":"Cutanéo-muqueuse, neurologique (méningo-encéphalite), systémique","accept":["cutanéo-muqueuse, neurologique et systémique","cutanéomuqueuse, neurologique, systémique"],"keywords":["cutan","neurolog","systémi"],"explanation":"La forme cutanéo-muqueuse n'entraîne pas de mortalité ; la forme neurologique (méningo-encéphalite) tue dans 15 % des cas avec des séquelles fréquentes ; la forme systémique est gravissime (mortalité de 40 à 70 %).","src":"p. 218"},{"id":"d168-qroc-017","type":"QROC","rank":"A","objective":"d168-obj-05","tags":["clinique"],"difficulty":2,"question":"Quels signes fonctionnels précèdent les vésicules d'une récurrence herpétique et sont stéréotypés chez un patient donné ?","answer":"Les prodromes : dysesthésie cuisante, picotements, prurit","accept":["prodromes","picotements","dysesthésie","prurit"],"keywords":["prodrome"],"explanation":"Quelques heures avant les vésicules groupées en bouquet, le patient ressent une dysesthésie cuisante, des picotements ou un prurit, toujours les mêmes pour lui, parfois avec un érythème localisé.","src":"p. 219"},{"id":"d168-qroc-018","type":"QROC","rank":"A","objective":"d168-obj-12","tags":["clinique"],"difficulty":1,"question":"Où siège précisément l'herpès labial récurrent, appelé « bouton de fièvre » ?","answer":"À la jonction entre la demi-muqueuse labiale et la peau","accept":["jonction demi-muqueuse et peau","jonction demi-muqueuse peau","jonction peau muqueuse","jonction cutanéo-muqueuse"],"keywords":["jonction"],"explanation":"Le bouton de fièvre siège à la jonction entre la demi-muqueuse et la peau. La localisation labiale est la plus fréquente des récurrences (labiale, puis génitale, puis cutanée, nasale et oculaire) ; le diagnostic différentiel est l'aphte.","src":"p. 219"},{"id":"d168-qroc-019","type":"QROC","rank":"A","objective":"d168-obj-05","tags":["diagnostic"],"difficulty":3,"question":"Devant un herpès génital aux lésions atypiques (ulcérations aphtoïdes, fissures, œdème), quel argument oriente vers le diagnostic ?","answer":"Le caractère récidivant avec prodromes et localisation stéréotypés","accept":["récidivant avec prodromes et localisations stéréotypés","prodromes et localisations stéréotypés","caractère récidivant et stéréotypé"],"keywords":["récidiv","stéréotyp"],"explanation":"Dans les formes atypiques d'herpès génital, c'est la répétition des épisodes avec les mêmes prodromes et la même localisation chez un patient donné qui oriente. Une forme atypique justifie en outre une confirmation virologique (PCR).","src":"p. 220-221, 223"},{"id":"d168-qroc-020","type":"QROC","rank":"B","objective":"d168-obj-05","tags":["clinique"],"difficulty":2,"question":"Quelle lésion cutanée à triple contour, de siège acral, caractérise l'érythème polymorphe post-herpétique ?","answer":"La cocarde","accept":["cocarde","cocardes","lésions en cocarde"],"keywords":["cocarde"],"explanation":"L'érythème polymorphe est une réaction immuno-allergique survenant 5 à 15 jours après l'infection herpétique : papules en cocarde des mains et des pieds, associées à une atteinte muqueuse conjonctivo-oro-génitale érosive.","src":"p. 222"},{"id":"d168-qroc-021","type":"QROC","rank":"B","objective":"d168-obj-05","tags":["étiologie"],"difficulty":1,"question":"Quel est le principal facteur étiologique (environ 50 % des cas) de l'érythème polymorphe ?","answer":"L'infection herpétique (primo-infection, récurrence ou excrétion virale)","accept":["infection herpétique","herpès","HSV","infection à HSV"],"keywords":["herp"],"explanation":"L'infection herpétique (primo-infection, récurrence ou simple excrétion virale) est en cause dans environ 50 % des érythèmes polymorphes, 5 à 15 jours après l'épisode.","src":"p. 222"},{"id":"d168-qroc-022","type":"QROC","rank":"A","objective":"d168-obj-14","tags":["diagnostic"],"difficulty":1,"question":"Dans quelle situation le diagnostic d'herpès cutanéo-muqueux est-il uniquement clinique ?","answer":"Forme typique chez un patient sans terrain à risque","accept":["forme typique","formes typiques","forme typique et terrain non à risque"],"keywords":["typique"],"explanation":"Une forme typique sur un terrain non à risque ne nécessite pas de confirmation virologique. Celle-ci est indiquée pour une forme atypique, sévère ou compliquée, une atteinte viscérale ou un immunodéprimé.","src":"p. 223"},{"id":"d168-qroc-023","type":"QROC","rank":"A","objective":"d168-obj-14","tags":["paraclinique","diagnostic"],"difficulty":1,"question":"Quelle est la technique de référence pour confirmer une infection à HSV sur une lésion récente ?","answer":"La PCR (détection du génome viral)","accept":["PCR","PCR HSV","détection du génome viral par PCR"],"keywords":["pcr"],"explanation":"La PCR est très sensible, très spécifique, rapide (résultat en moins de 24 heures) et a remplacé la culture. Elle s'effectue sur un écouvillonnage des sérosités d'une vésicule récente, placé en milieu de transport spécifique.","src":"p. 223"},{"id":"d168-qroc-024","type":"QROC","rank":"A","objective":"d168-obj-15","tags":["traitement","pièges"],"difficulty":1,"question":"Quelle catégorie de traitements n'a pas montré d'efficacité dans l'herpès cutanéo-muqueux ?","answer":"Les traitements locaux (topiques)","accept":["traitements locaux","traitement local","topiques","topique","voie locale"],"keywords":["loca"],"explanation":"Les traitements locaux n'ont pas montré d'efficacité. Les antiviraux efficaces sont l'aciclovir et le valaciclovir par voie orale, et l'aciclovir IV dans les formes graves.","src":"p. 224"},{"id":"d168-qroc-025","type":"QROC","rank":"A","objective":"d168-obj-15","tags":["traitement"],"difficulty":2,"question":"Quel est le mécanisme d'action de l'aciclovir ?","answer":"Il inhibe l'ADN polymérase virale (forme active : aciclovir triphosphate)","accept":["inhibe l'ADN polymérase virale","inhibition de l'ADN polymérase virale","inhibiteur de l'ADN polymérase virale","inhibe l'ADN polymérase"],"keywords":["polymérase"],"explanation":"Dans les cellules infectées par HSV, l'aciclovir est phosphorylé en aciclovir triphosphate, forme active qui inhibe l'ADN polymérase virale. Le valaciclovir est sa prodrogue, de meilleure biodisponibilité.","src":"p. 224"},{"id":"d168-qroc-026","type":"QROC","rank":"A","objective":"d168-obj-15","tags":["traitement"],"difficulty":1,"question":"Quel antiviral administré par voie IV est utilisé en cas de résistance du virus à l'aciclovir ?","answer":"Le foscarnet","accept":["foscarnet","le foscarnet"],"keywords":["foscarnet"],"explanation":"Des souches résistantes à l'aciclovir émergent rarement, chez les sujets immunodéprimés ; le foscarnet IV est alors utilisé.","src":"p. 224"},{"id":"d168-qroc-027","type":"QROC","rank":"A","objective":"d168-obj-15","tags":["traitement","pièges"],"difficulty":2,"question":"Quel traitement antiviral prescrire pour une récurrence banale d'herpès orofacial ?","answer":"Aucun : pas d'indication à un traitement antiviral","accept":["aucun","pas de traitement","pas d'indication","pas d'antiviral"],"keywords":["aucun"],"explanation":"Il n'y a pas d'indication à un antiviral pour une récurrence banale d'herpès orofacial. Un traitement préventif n'est discuté que pour des poussées fréquentes, invalidantes ou compliquées, avec éviction des facteurs déclenchants (photoprotection).","src":"p. 224"},{"id":"d168-qroc-028","type":"QROC","rank":"A","objective":"d168-obj-15","tags":["traitement","suivi"],"difficulty":2,"question":"À partir de combien de récurrences par an d'herpès génital un traitement antiviral préventif est-il proposé, et pour quelle durée avant réévaluation ?","answer":"Plus de 6 récurrences par an ; 6 à 12 mois puis réévaluation","accept":["plus de 6 récurrences par an, 6 à 12 mois","plus de 6 par an, 6 à 12 mois"],"keywords":["6","12"],"explanation":"Le traitement préventif (aciclovir ou valaciclovir per os) est proposé en cas de plus de 6 récurrences par an ; il dure 6 à 12 mois, puis la situation est réévaluée. Les facteurs déclenchants doivent être évités.","src":"p. 225"},{"id":"d168-qroc-029","type":"QROC","rank":"A","objective":"d168-obj-15","tags":["grossesse","traitement"],"difficulty":2,"question":"Quelle conduite obstétricale est recommandée si des lésions d'herpès génital sont présentes au moment du travail ?","answer":"Une césarienne systématique","accept":["césarienne","césarienne systématique"],"keywords":["césarienne"],"explanation":"Des lésions herpétiques au moment du travail imposent une césarienne systématique. En l'absence de lésions, la voie basse est possible, notamment si la primo-infection date de plus d'un mois.","src":"p. 225"},{"id":"d168-qroc-030","type":"QROC","rank":"A","objective":"d168-obj-08","tags":["définition"],"difficulty":1,"question":"Dans l'infection par le VZV, que représentent respectivement la varicelle et le zona ?","answer":"Varicelle = primo-infection ; zona = récurrence localisée","accept":["varicelle primo-infection, zona récurrence","primo-infection et récurrence","primo-infection puis récurrence","varicelle : primo-infection ; zona : récurrence"],"keywords":["primo","récurrence"],"explanation":"Le VZV (virus à ADN, famille des Herpesviridae, contamination interhumaine stricte) donne la varicelle lors de la primo-infection et le zona lors d'une récurrence localisée.","src":"p. 226, 240"},{"id":"d168-qroc-031","type":"QROC","rank":"A","objective":"d168-obj-07","tags":["clinique"],"difficulty":1,"question":"Quelle est la durée d'incubation de la varicelle ?","answer":"14 jours","accept":["14 jours","14","deux semaines"],"keywords":["14"],"explanation":"L'incubation est de 14 jours : chez un enfant scolarisé ou vivant en collectivité, on retrouve une notion de contage 14 jours avant l'éruption.","src":"p. 228, 240"},{"id":"d168-qroc-032","type":"QROC","rank":"A","objective":"d168-obj-10","tags":["clinique"],"difficulty":1,"question":"Quelle est la lésion élémentaire cutanée de la varicelle ?","answer":"Une vésicule ombiliquée","accept":["vésicule ombiliquée","vésicules ombiliquées","vésicule en goutte de rosée","vésicules en gouttes de rosée"],"keywords":["vésicule","ombiliqu"],"explanation":"Sur la peau, il s'agit de vésicules ombiliquées (au début en « gouttes de rosée »), à contenu clair puis trouble. Sur les muqueuses, les vésicules sont fragiles et éphémères et laissent des érosions arrondies ou ovalaires.","src":"p. 228"},{"id":"d168-qroc-033","type":"QROC","rank":"A","objective":"d168-obj-10","tags":["clinique"],"difficulty":2,"question":"Quelle est l'évolution topographique de l'éruption de la varicelle ?","answer":"Descendante, à partir du cuir chevelu","accept":["descendante","début au cuir chevelu","à partir du cuir chevelu","descendante, débutant au cuir chevelu"],"keywords":["descend"],"explanation":"L'éruption débute au cuir chevelu et descend ; elle comporte des lésions d'âges différents (macules, vésicules, ombilication, croûtes), avec un prurit marqué et des érosions muqueuses arrondies bien séparées.","src":"p. 228"},{"id":"d168-qroc-034","type":"QROC","rank":"A","objective":"d168-obj-07","tags":["complications","pédiatrie"],"difficulty":2,"question":"Quels germes surinfectent le plus souvent les lésions de varicelle chez l'enfant ?","answer":"Staphylocoque doré et streptocoque","accept":["staphylocoque doré et streptocoque","staphylocoque et streptocoque","staphylocoque doré, streptocoque","streptocoque et staphylocoque doré"],"keywords":["staphylo","streptoc"],"explanation":"Ces germes provoquent surtout une impétiginisation secondaire (placards croûteux mélicériques). Plus rarement : dermohypodermite ou fasciite nécrosante streptococcique, septicémie, arthrites.","src":"p. 229"},{"id":"d168-qroc-035","type":"QROC","rank":"A","objective":"d168-obj-07","tags":["complications","urgence"],"difficulty":2,"question":"Quelle surinfection bactérienne exceptionnelle de la varicelle constitue une grande urgence médico-chirurgicale ?","answer":"La dermohypodermite / fasciite nécrosante streptococcique","accept":["fasciite nécrosante","dermohypodermite nécrosante","dermohypodermite et fasciite nécrosante","fasciite nécrosante streptococcique"],"keywords":["nécrosante"],"explanation":"Elle se manifeste par des placards inflammatoires nécrotiques rapidement extensifs et un sepsis sévère ; les pronostics vital et fonctionnel sont engagés. C'est une raison d'éviter les AINS au cours de la varicelle.","src":"p. 229, 237"},{"id":"d168-qroc-036","type":"QROC","rank":"A","objective":"d168-obj-07","tags":["pièges","complications"],"difficulty":1,"question":"Quel médicament est formellement contre-indiqué au cours de la varicelle car il expose au syndrome de Reye ?","answer":"L'aspirine","accept":["aspirine","l'aspirine"],"keywords":["aspirine"],"explanation":"Le syndrome de Reye associe encéphalopathie et stéatose hépatique et est mortel dans 80 % des cas. Pour la fièvre, on donne du paracétamol ; les AINS sont également à éviter (risque de fasciite nécrosante).","src":"p. 230, 237"},{"id":"d168-qroc-037","type":"QROC","rank":"A","objective":"d168-obj-07","tags":["complications"],"difficulty":2,"question":"Quels deux facteurs favorisent la pneumopathie varicelleuse de l'adulte ?","answer":"Le tabagisme et la grossesse","accept":["tabagisme et grossesse","tabac et grossesse","grossesse et tabagisme","tabagisme, grossesse"],"keywords":["tab","grossesse"],"explanation":"La pneumopathie varicelleuse est rare (5 %) mais grave : toux, dyspnée, fièvre et hémoptysies 1 à 6 jours après l'éruption, opacités micro- et macronodulaires multiples. Elle cause 30 % des décès de la varicelle de l'adulte.","src":"p. 229-230"},{"id":"d168-qroc-038","type":"QROC","rank":"A","objective":"d168-obj-07","tags":["grossesse","complications"],"difficulty":2,"question":"Quel risque court le fœtus lorsque la varicelle maternelle survient avant la 20e semaine de gestation ?","answer":"Une fœtopathie varicelleuse","accept":["fœtopathie varicelleuse","fœtopathie"],"keywords":["fœtopathie"],"explanation":"Entre la 13e et la 20e semaine, la fœtopathie est rare mais grave : atteintes neurologiques, ophtalmologiques et musculo-squelettiques, voire mort in utero ; une surveillance en centre de diagnostic anténatal est nécessaire.","src":"p. 231"},{"id":"d168-qroc-039","type":"QROC","rank":"A","objective":"d168-obj-07","tags":["grossesse","pédiatrie"],"difficulty":2,"question":"Dans quel intervalle autour de l'accouchement une varicelle maternelle expose-t-elle l'enfant à une varicelle néonatale ?","answer":"Dans les 5 jours précédant ou les 2 jours suivant l'accouchement","accept":["5 jours avant et 2 jours après","5 jours avant à 2 jours après","5 jours précédant et 2 jours suivant l'accouchement","de J-5 à J+2"],"keywords":["5","2"],"explanation":"La varicelle néonatale est grave : septicémie avec atteintes multiviscérales (pulmonaires et neurologiques surtout), décès dans 30 % des cas. Un traitement par aciclovir IV est indiqué.","src":"p. 231, 237"},{"id":"d168-qroc-040","type":"QROC","rank":"A","objective":"d168-obj-15","tags":["traitement","pédiatrie"],"difficulty":1,"question":"Quel traitement antiviral prescrire pour une varicelle bénigne de l'enfant immunocompétent ?","answer":"Aucun : le traitement est symptomatique","accept":["aucun","pas de traitement antiviral","pas d'antiviral","traitement symptomatique"],"keywords":["aucun"],"explanation":"Il n'y a pas d'indication à un antiviral et l'éviction de collectivité n'est pas obligatoire. On traite la fièvre (paracétamol) et le prurit, et on prévient la surinfection (douches, chlorhexidine aqueuse, ongles courts, pas de talc).","src":"p. 237"},{"id":"d168-qroc-041","type":"QROC","rank":"A","objective":"d168-obj-15","tags":["traitement","urgence"],"difficulty":2,"question":"Quel antiviral, et par quelle voie, pour une varicelle grave ou compliquée (pneumopathie, immunodépression...) ?","answer":"L'aciclovir par voie IV","accept":["aciclovir IV","aciclovir par voie IV","aciclovir intraveineux"],"keywords":["aciclovir","iv"],"explanation":"L'aciclovir IV est recommandé notamment chez le nouveau-né, la femme enceinte dont la varicelle survient 8 à 10 jours avant l'accouchement, l'enfant de moins de 1 an avec une forme grave, en cas de complication viscérale et en cas d'immunodépression.","src":"p. 237"},{"id":"d168-qroc-042","type":"QROC","rank":"A","objective":"d168-obj-08","tags":["clinique"],"difficulty":2,"question":"Quelles sont les deux caractéristiques de la distribution cutanée de l'éruption du zona ?","answer":"Unilatérale et radiculaire (métamérique)","accept":["unilatérale et métamérique","radiculaire et unilatérale","unilatérale, radiculaire","unilatérale et radiculaire"],"keywords":["unilat","radicul"],"explanation":"Le zona touche un dermatome (territoire sensitif cutanéo-muqueux), avec une distribution radiculaire (métamérique) et unilatérale ; l'éruption n'est étendue que dans les formes graves.","src":"p. 232"},{"id":"d168-qroc-043","type":"QROC","rank":"A","objective":"d168-obj-08","tags":["clinique"],"difficulty":2,"question":"Quelle est la nature des douleurs du zona, qui peuvent précéder l'éruption ?","answer":"Des douleurs neuropathiques radiculaires et unilatérales","accept":["douleurs neuropathiques","douleurs radiculaires","neuropathiques","douleurs neuropathiques radiculaires"],"keywords":["neuropath"],"explanation":"Ces douleurs sont fréquentes et intenses, en coup de poignard ou en brûlure avec paroxysmes. Elles peuvent précéder l'éruption, l'accompagner ou persister après elle (algies post-zostériennes).","src":"p. 232"},{"id":"d168-qroc-044","type":"QROC","rank":"A","objective":"d168-obj-13","tags":["clinique"],"difficulty":2,"question":"Quelle est la localisation la plus fréquente du zona (environ la moitié des cas) ?","answer":"Zona intercostal ou dorsolombaire, en demi-ceinture","accept":["intercostal","dorsolombaire","thoracique","zona thoracique","demi-ceinture"],"keywords":["intercostal"],"explanation":"Le zona intercostal ou dorsolombaire (réactivation dans les ganglions rachidiens) réalise une éruption en demi-ceinture ; le zona de membre est linéaire, suivant le trajet radiculaire.","src":"p. 232"},{"id":"d168-qroc-045","type":"QROC","rank":"A","objective":"d168-obj-13","tags":["complications","clinique"],"difficulty":2,"question":"Dans un zona du territoire du nerf ophtalmique (V1), quel signe cutané fait craindre une atteinte oculaire ?","answer":"Une éruption narinaire et de la cloison nasale","accept":["éruption narinaire","atteinte du rameau nasal interne","rameau nasal interne","vésicules narinaires","cloison nasale"],"keywords":["narin"],"explanation":"L'éruption narinaire et de la cloison traduit l'atteinte du rameau nasal interne et expose à une atteinte oculaire ; un avis ophtalmologique est nécessaire.","src":"p. 233"},{"id":"d168-qroc-046","type":"QROC","rank":"A","objective":"d168-obj-09","tags":["clinique","complications"],"difficulty":2,"question":"Quel ganglion est réactivé dans le zona auriculaire, dont les lésions cutanées sont limitées à la zone de Ramsay-Hunt ?","answer":"Le ganglion géniculé","accept":["ganglion géniculé","géniculé"],"keywords":["génicul"],"explanation":"Les lésions touchent le conduit auditif externe et la conque. L'éruption est discrète mais l'otalgie est très intense, avec adénopathie prétragienne, anesthésie des deux tiers antérieurs de l'hémilangue, ± paralysie faciale et troubles cochléovestibulaires.","src":"p. 233-234"},{"id":"d168-qroc-047","type":"QROC","rank":"A","objective":"d168-obj-09","tags":["complications"],"difficulty":2,"question":"Comment nomme-t-on les douleurs neuropathiques de désafférentation qui persistent ou réapparaissent dans le territoire d'un zona ?","answer":"Les algies post-zostériennes","accept":["algies post-zostériennes","douleurs post-zostériennes","algies postzostériennes","algie post-zostérienne"],"keywords":["zostér"],"explanation":"Ces douleurs s'accompagnent d'une hypoesthésie du territoire atteint. Elles sont de plus en plus fréquentes avec l'âge, difficiles à traiter et altèrent la qualité de vie ; un antiviral précoce après 50 ans vise à les prévenir.","src":"p. 232, 236, 239"},{"id":"d168-qroc-048","type":"QROC","rank":"A","objective":"d168-obj-14","tags":["paraclinique","diagnostic"],"difficulty":1,"question":"Quel examen de référence confirme un zona, sur le liquide d'une vésicule récente ?","answer":"La PCR VZV","accept":["PCR","PCR VZV"],"keywords":["pcr"],"explanation":"La PCR VZV sur le liquide d'une vésicule récente est la technique de référence. Le cytodiagnostic, la biopsie et la sérologie n'ont pas d'intérêt pratique.","src":"p. 236"},{"id":"d168-qroc-049","type":"QROC","rank":"A","objective":"d168-obj-08","tags":["diagnostic","pièges"],"difficulty":2,"question":"Quelle sérologie faut-il demander devant un zona chez un adulte jeune ?","answer":"La sérologie VIH","accept":["VIH","sérologie VIH"],"keywords":["vih"],"explanation":"Un zona chez l'adulte jeune fait rechercher une immunodépression par une sérologie VIH ; la NFS recherche une hémopathie de type leucémie lymphoïde chronique.","src":"p. 236, 240"},{"id":"d168-qroc-050","type":"QROC","rank":"A","objective":"d168-obj-15","tags":["traitement"],"difficulty":2,"question":"Quelles sont les trois situations qui justifient un traitement antiviral systémique d'un zona ?","answer":"Immunodépression, âge à partir de 50 ans, zona ophtalmique","accept":["immunodépression, 50 ans, zona ophtalmique","immunodépression, zona ophtalmique, 50 ans"],"keywords":["immunod","50","ophtalm"],"explanation":"L'antiviral n'est indiqué que dans ces trois situations, à débuter dans les 72 heures suivant le début de l'éruption. Il n'y a pas d'éviction de collectivité.","src":"p. 238"},{"id":"d168-qroc-051","type":"QROC","rank":"A","objective":"d168-obj-15","tags":["traitement"],"difficulty":2,"question":"Quel traitement antiviral oral (molécule et durée) est donné à un immunocompétent de plus de 50 ans ayant un zona non ophtalmique ?","answer":"Valaciclovir pendant 7 jours","accept":["valaciclovir 7 jours","valaciclovir pendant 7 jours","valaciclovir per os 7 jours","valaciclovir PO 7 jours"],"keywords":["valaciclovir","7"],"explanation":"Chez l'immunocompétent, on utilise la voie orale (valaciclovir 7 jours, AMM) pour prévenir les algies post-zostériennes après 50 ans ; chez l'immunodéprimé, on utilise l'aciclovir IV (au moins 7 à 10 jours).","src":"p. 238-239"},{"id":"d168-qroc-052","type":"QROC","rank":"A","objective":"d168-obj-15","tags":["traitement","pièges"],"difficulty":3,"question":"Dans le zona ophtalmique, quelles sont les deux seules indications des corticoïdes locaux, après avis ophtalmologique ?","answer":"Kératites immunologiques et uvéites antérieures","accept":["kératites immunologiques et uvéites antérieures","kératite immunologique et uvéite antérieure","uvéites antérieures et kératites immunologiques"],"keywords":["immunolog","uvé"],"explanation":"Les corticoïdes locaux sont classiquement contre-indiqués dans le zona ophtalmique. L'antiviral reste toujours nécessaire, éventuellement complété par une pommade ophtalmologique à l'aciclovir après avis spécialisé.","src":"p. 239"},{"id":"d168-qroc-053","type":"QROC","rank":"A","objective":"d168-obj-15","tags":["traitement"],"difficulty":2,"question":"Quels sont les deux antalgiques à visée neuropathique ayant l'AMM dans les algies post-zostériennes ?","answer":"Amitriptyline et gabapentine","accept":["amitriptyline et gabapentine","gabapentine et amitriptyline","amitriptyline, gabapentine"],"keywords":["amitriptyline","gabapentine"],"explanation":"Amitriptyline et gabapentine ont l'AMM ; carbamazépine et prégabaline sont hors AMM. En local : emplâtre de lidocaïne (12 heures par jour au maximum) ou capsaïcine. Pas de corticothérapie générale en phase aiguë.","src":"p. 239"},{"id":"d168-qroc-054","type":"QROC","rank":"B","objective":"d168-obj-18","tags":["prévention"],"difficulty":1,"question":"Quelle population est ciblée par la recommandation de vaccination contre le zona ?","answer":"Les adultes de 65 à 74 ans révolus","accept":["65 à 74 ans","65-74 ans","65 à 74 ans révolus","adultes de 65 à 74 ans"],"keywords":["65","74"],"explanation":"Le vaccin zona (virus vivant atténué, une dose, efficacité de 70 %) est recommandé de 65 à 74 ans révolus, y compris chez les sujets ayant déjà eu un zona ; il est contre-indiqué chez les immunodéprimés.","src":"p. 239"},{"id":"d168-qcm-101","type":"QRM","rank":"A","objective":"d168-obj-05","tags":["clinique","diagnostic"],"difficulty":1,"stem":"Un enfant de 3 ans est amené pour une fièvre à 39 °C, une hypersialorrhée et un refus de s'alimenter depuis 2 jours. L'examen montre des gencives tuméfiées et saignantes, des érosions buccales coalescentes à contours polycycliques recouvertes d'un enduit blanchâtre, quelques vésicules croûteuses du menton et des adénopathies cervicales sensibles. Quelles propositions sont exactes ?","options":[{"t":"Il s'agit d'une primo-infection herpétique buccale, le plus souvent due à HSV1","ok":true,"why":"La gingivostomatite herpétique aiguë est la forme buccale de la primo-infection du petit enfant ; HSV1 est plus fréquent que HSV2."},{"t":"Une aphtose est le diagnostic le plus probable","ok":false,"why":"L'aphtose ne donne ni fièvre, ni signes généraux, ni adénopathies ; le contexte fébrile avec vésicules péribuccales est celui de l'herpès."},{"t":"L'impossibilité de s'alimenter est un signe de gravité","ok":true,"why":"Une dysphagie majeure rendant l'alimentation impossible est un signe de gravité de la gingivostomatite herpétique."},{"t":"Des vésicules ou des croûtes péribuccales peuvent accompagner les érosions muqueuses","ok":true,"why":"Des vésicules en bouquet et/ou des croûtes peuvent siéger en périphérie des lésions, sur le revêtement cutané ou semi-muqueux (lèvres, menton)."},{"t":"Un antiviral appliqué localement est le traitement de référence","ok":false,"why":"Les traitements locaux n'ont pas montré d'efficacité ; les antiviraux se prescrivent par voie générale."}],"explanation":"Tableau typique de gingivostomatite herpétique aiguë du petit enfant : érosions polycycliques, fièvre, adénopathies cervicales. L'évolution est favorable en 10 à 15 jours ; les diagnostics différentiels sont l'aphtose, l'érythème polymorphe ou le syndrome de Stevens-Johnson et l'herpangine (coxsackie).","src":"p. 214-215"},{"id":"d168-qcm-102","type":"QRM","rank":"A","objective":"d168-obj-11","tags":["clinique","complications"],"difficulty":2,"stem":"Une femme de 22 ans consulte pour des douleurs vulvaires très intenses d'apparition brutale, une fièvre à 38,5 °C et des courbatures. La muqueuse vulvaire est œdémateuse, avec des érosions arrondies confluentes à contours polycycliques et des adénopathies inguinales sensibles. Elle n'arrive plus à uriner. Quelles propositions sont exactes ?","options":[{"t":"Il s'agit d'une primo-infection herpétique génitale","ok":true,"why":"Vulvovaginite aiguë brutale, fébrile et très douloureuse, avec érosions polycycliques : tableau typique."},{"t":"La rétention d'urines est un signe de gravité","ok":true,"why":"Rétention urinaire réactionnelle, liée à la douleur : signe de gravité (forme sévère, avec sondage urinaire et antalgiques)."},{"t":"L'absence de vésicule intacte à l'examen élimine le diagnostic","ok":false,"why":"Sur les muqueuses, les vésicules sont éphémères et souvent absentes : on voit surtout des érosions."},{"t":"Les érosions de la paroi vaginale et du col utérin doivent être recherchées systématiquement","ok":false,"why":"Il ne faut pas les rechercher systématiquement : l'examen est très douloureux."},{"t":"Un dépistage des autres IST fait partie de la prise en charge","ok":true,"why":"L'herpès génital est une IST : le dépistage des IST et les mesures associées font partie de la prise en charge d'une primo-infection."}],"explanation":"La primo-infection génitale (HSV2 ou HSV1) associe vulvovaginite aiguë fébrile très douloureuse, adénopathies inguinales, et parfois rétention d'urines. L'évolution est favorable en 2 à 3 semaines.","src":"p. 215-216, 225"},{"id":"d168-qcm-103","type":"QRM","rank":"B","objective":"d168-obj-06","tags":["étiologie","clinique"],"difficulty":1,"stem":"À propos des facteurs favorisant les récurrences herpétiques, quelles propositions sont exactes ?","options":[{"t":"Les rayons ultraviolets","ok":true,"why":"Les UV figurent parmi les facteurs physiques favorisants (tableau 10.1)."},{"t":"Le tabagisme","ok":false,"why":"Le tabagisme favorise la pneumopathie varicelleuse ; il ne figure pas parmi les facteurs favorisants des récurrences herpétiques."},{"t":"Le cycle menstruel (herpès cataménial)","ok":true,"why":"Le cycle menstruel est un facteur physiologique de récurrence, responsable de l'herpès dit cataménial."},{"t":"Un âge supérieur à 50 ans","ok":false,"why":"L'âge supérieur à 50 ans est une caractéristique épidémiologique du zona, pas un facteur de récurrence herpétique du tableau 10.1."},{"t":"Les immunosuppresseurs","ok":true,"why":"Ils font partie des facteurs iatrogènes, avec la chirurgie ou le laser dans le territoire."}],"explanation":"Tableau 10.1 : infections intercurrentes (fongique, bactérienne, virale fébrile), UV, froid, traumatisme local, cycle menstruel, rapports sexuels (herpès génital), immunodépression, stress, asthénie, immunosuppresseurs, chirurgie ou laser dans le territoire.","src":"p. 219"},{"id":"d168-qcm-104","type":"QRM","rank":"A","objective":"d168-obj-05","tags":["clinique","pédiatrie","urgence"],"difficulty":2,"stem":"Un nourrisson de 8 mois atteint d'une dermatite atopique sévère présente depuis 24 heures une fièvre et une altération de l'état général. Une éruption croûteuse et érosive du visage s'étend rapidement au tronc ; elle comporte des vésicules hémorragiques, des pustules et une ombilication centrale des lésions. Quelles propositions sont exactes ?","options":[{"t":"Il s'agit d'une surinfection herpétique de la dermatite atopique","ok":true,"why":"L'éruption vésiculeuse profuse fébrile sur dermatite atopique est une surinfection par HSV (primo-contact ou récurrence)."},{"t":"Ce tableau est appelé syndrome de Kaposi-Juliusberg","ok":true,"why":"C'est le nom de la forme grave d'herpès survenant sur dermatite atopique."},{"t":"Un traitement antiviral par voie IV est nécessaire","ok":true,"why":"L'évolution est favorable en quelques jours sous traitement antiviral IV."},{"t":"L'éruption débute habituellement aux membres, en épargnant le visage","ok":false,"why":"Le début est préférentiel au visage, avec extension à tout le corps."},{"t":"Ce syndrome ne peut survenir que lors d'une primo-infection herpétique","ok":false,"why":"Il peut survenir lors d'un primo-contact comme lors d'une récurrence du virus."}],"explanation":"Le syndrome de Kaposi-Juliusberg est une forme grave : sujet jeune ou nourrisson atopique sévère, fièvre, éruption vésiculeuse, érosive et croûteuse profuse à extension rapide, vésicules hémorragiques, pustules et ombilication centrale. Traitement antiviral IV.","trap":"Ne pas confondre avec une simple impétiginisation : la fièvre, l'altération de l'état général et les vésicules ombiliquées profuses sur dermatite atopique doivent faire évoquer l'herpès.","src":"p. 217-218"},{"id":"d168-qcm-105","type":"QRM","rank":"A","objective":"d168-obj-05","tags":["pédiatrie","complications"],"difficulty":2,"stem":"À propos de l'herpès néonatal, quelles propositions sont exactes ?","options":[{"t":"La contamination peut survenir in utero, à l'accouchement ou après la naissance","ok":true,"why":"Trois modes : transplacentaire, passage dans la filière génitale contaminante, contamination postnatale par la mère ou l'entourage."},{"t":"La forme neurologique évolue le plus souvent sans séquelle","ok":false,"why":"La méningo-encéphalite herpétique néonatale a une mortalité d'environ 15 % et des séquelles fréquentes."},{"t":"La forme cutanéo-muqueuse n'entraîne pas de mortalité","ok":true,"why":"Contrairement aux formes neurologique et systémique, la forme cutanéo-muqueuse n'est pas mortelle."},{"t":"La forme systémique a un bon pronostic, avec une mortalité inférieure à 5 %","ok":false,"why":"La forme systémique est gravissime, avec une mortalité de 40 à 70 %."},{"t":"La contamination ne se fait que par voie transplacentaire","ok":false,"why":"Il existe aussi la contamination lors de l'accouchement et la contamination postnatale."}],"explanation":"L'herpès néonatal comprend trois formes : cutanéo-muqueuse (pas de mortalité), neurologique (méningo-encéphalite, mortalité de 15 %, séquelles fréquentes) et systémique (mortalité de 40 à 70 %).","src":"p. 211, 218"},{"id":"d168-qcm-106","type":"QRM","rank":"A","objective":"d168-obj-14","tags":["paraclinique","diagnostic"],"difficulty":2,"stem":"À propos du diagnostic virologique d'une infection à HSV, quelles propositions sont exactes ?","options":[{"t":"Une sérologie IgG positive suffit pour affirmer une primo-infection","ok":false,"why":"Les IgG sont positives chez 80 % des adultes : elles ne signent qu'un contact ancien. Seule une séroconversion entre deux prélèvements à 10 jours d'intervalle est informative."},{"t":"La détection du génome viral par PCR est la technique de référence","ok":true,"why":"La PCR est très sensible, très spécifique et rapide ; elle a remplacé la culture."},{"t":"La culture virale a remplacé la PCR","ok":false,"why":"C'est l'inverse : la PCR a remplacé la culture virale."},{"t":"Le prélèvement peut être réalisé sur une lésion croûteuse ancienne","ok":false,"why":"La sensibilité dépend de conditions optimales : lésion récente, écouvillonnage des sérosités d'une vésicule, milieu de transport spécifique, acheminement rapide."},{"t":"Un diagnostic virologique est systématique devant toute forme typique chez un sujet sans terrain à risque","ok":false,"why":"Dans les formes typiques sans terrain à risque, le diagnostic est clinique."}],"explanation":"Le diagnostic est avant tout clinique. La confirmation virologique par PCR est réservée aux formes atypiques, sévères ou compliquées, aux atteintes viscérales et aux terrains à risque.","src":"p. 223-224"},{"id":"d168-qcm-107","type":"QRM","rank":"A","objective":"d168-obj-15","tags":["traitement"],"difficulty":2,"stem":"À propos des antiviraux actifs sur HSV, quelles propositions sont exactes ?","options":[{"t":"L'aciclovir est transformé dans les cellules infectées en une forme active qui inhibe l'ADN polymérase virale","ok":true,"why":"Phosphorylation en aciclovir triphosphate, forme active inhibant l'ADN polymérase virale."},{"t":"Le valaciclovir est une prodrogue de l'aciclovir à meilleure biodisponibilité","ok":true,"why":"Le valaciclovir est une prodrogue de l'aciclovir ; ces traitements sont virostatiques."},{"t":"Le foscarnet IV est une option en cas de résistance du virus à l'aciclovir","ok":true,"why":"Le foscarnet s'administre par voie IV dans les formes résistantes à l'aciclovir."},{"t":"Les antiviraux éliminent le virus latent des ganglions sensitifs","ok":false,"why":"Ce sont des virostatiques actifs sur les populations virales en réplication ; le ganglion est un sanctuaire peu accessible au système immunitaire et aux traitements."},{"t":"Les souches résistantes à l'aciclovir émergent rarement, chez les sujets immunodéprimés","ok":true,"why":"L'émergence de souches résistantes est rare et concerne les immunodéprimés."}],"explanation":"L'aciclovir (et sa prodrogue valaciclovir) est le traitement de référence ; le foscarnet IV est réservé aux résistances. Les traitements locaux n'ont pas montré d'efficacité.","src":"p. 212, 224"},{"id":"d168-qcm-108","type":"QRM","rank":"A","objective":"d168-obj-15","tags":["traitement","suivi"],"difficulty":2,"stem":"Un homme de 30 ans a une récurrence d'herpès génital environ une fois par mois depuis un an, avec un retentissement important. Quelles propositions sont exactes ?","options":[{"t":"Un traitement préventif par aciclovir ou valaciclovir per os peut être proposé","ok":true,"why":"Le traitement préventif est indiqué en cas de plus de 6 récurrences par an."},{"t":"Une application locale d'antiviral suffit à prévenir les récurrences","ok":false,"why":"Les traitements locaux n'ont pas montré d'efficacité."},{"t":"Le traitement préventif est prescrit pour 6 à 12 mois, puis réévalué","ok":true,"why":"Durée de 6 à 12 mois avant réévaluation."},{"t":"Une fois instauré, le traitement préventif est poursuivi sans jamais être réévalué","ok":false,"why":"Une réévaluation est prévue après 6 à 12 mois."},{"t":"Pour une récurrence isolée, une ordonnance peut être remise au patient afin de débuter le traitement le plus tôt possible","ok":true,"why":"Le traitement des récurrences n'est pas systématique ; il est à débuter le plus tôt possible, le patient pouvant disposer de l'ordonnance."}],"explanation":"Herpès génital récurrent : traitement préventif (aciclovir ou valaciclovir PO, 6 à 12 mois puis réévaluation) si plus de 6 récurrences par an ; sinon traitement des poussées à débuter précocement.","src":"p. 225"},{"id":"d168-qcm-109","type":"QRM","rank":"A","objective":"d168-obj-15","tags":["grossesse","traitement"],"difficulty":2,"stem":"À propos de l'herpès génital chez la femme enceinte, quelles propositions sont exactes ?","options":[{"t":"Des lésions herpétiques génitales au moment du travail imposent une césarienne","ok":true,"why":"La césarienne est systématique en cas de lésions au moment du travail."},{"t":"Les récurrences, même fréquentes, n'exposent à aucun risque de transmission à l'enfant","ok":false,"why":"Les récurrences fréquentes exposent au risque de transmission maternofœtale."},{"t":"Une primo-infection survenue moins d'un mois avant l'accouchement justifie aciclovir ou valaciclovir per os jusqu'à l'accouchement","ok":true,"why":"Dans ce cas, le traitement oral est poursuivi jusqu'à l'accouchement."},{"t":"La primo-infection ne présente aucun risque pour la mère elle-même","ok":false,"why":"Elle expose la mère à un risque accru d'hépatite fulminante ou d'encéphalite."},{"t":"Si la poche des eaux est rompue depuis plus de 6 heures, la césarienne est systématique","ok":false,"why":"Dans cette situation, la césarienne n'a aucun intérêt ; un dépistage virologique est fait chez le nouveau-né."}],"explanation":"Herpès et grossesse : césarienne si lésions au moment du travail ; traitement oral de la primo-infection récente jusqu'à l'accouchement ; risque maternel (hépatite fulminante, encéphalite) et fœtal selon le moment de la contamination.","src":"p. 218, 225-226"},{"id":"d168-qcm-110","type":"QRM","rank":"A","objective":"d168-obj-07","tags":["clinique","pédiatrie"],"difficulty":1,"stem":"Un garçon de 6 ans, scolarisé, a depuis 24 heures une fièvre à 38,5 °C et une éruption très prurigineuse débutée au cuir chevelu. On observe sur le tronc et le visage des macules rouges, des vésicules à contenu clair, des vésicules ombiliquées et des croûtes, ainsi que des érosions buccales arrondies bien séparées. Quelles propositions sont exactes ?","options":[{"t":"L'éruption évolue de façon descendante","ok":true,"why":"L'évolution topographique de l'éruption est descendante, à partir du cuir chevelu."},{"t":"Un traitement antiviral systématique est indiqué","ok":false,"why":"Il n'y a pas d'indication à un antiviral dans la varicelle bénigne de l'enfant immunocompétent."},{"t":"La coexistence de lésions d'âges différents est caractéristique","ok":true,"why":"Macules, vésicules, vésicules ombiliquées et croûtes coexistent."},{"t":"Une éviction de collectivité est obligatoire","ok":false,"why":"L'éviction de collectivité n'est pas obligatoire."},{"t":"Les érosions muqueuses sont incompatibles avec le diagnostic","ok":false,"why":"Des érosions muqueuses arrondies et bien séparées sont habituellement associées."}],"explanation":"Varicelle typique : contage 14 jours avant, prodromes (catarrhe oculo-nasal), fièvre 38-39 °C, éruption descendante de vésicules ombiliquées d'âges différents, prurit intense, érosions muqueuses. Évolution rapidement favorable.","src":"p. 228, 237"},{"id":"d168-qcm-111","type":"QRM","rank":"A","objective":"d168-obj-07","tags":["complications"],"difficulty":2,"stem":"Parmi les propositions suivantes, lesquelles sont des complications possibles de la varicelle ?","options":[{"t":"Une impétiginisation secondaire par staphylocoque doré ou streptocoque","ok":true,"why":"C'est la surinfection bactérienne cutanée habituelle, essentiellement chez l'enfant."},{"t":"Un syndrome de Reye lié à la prise de paracétamol","ok":false,"why":"Le syndrome de Reye est lié à la prise d'aspirine, formellement contre-indiquée."},{"t":"Une fasciite nécrosante streptococcique, rare mais très grave","ok":true,"why":"C'est une grande urgence médico-chirurgicale, avec pronostics vital et fonctionnel engagés."},{"t":"Une pneumopathie plus fréquente chez l'enfant que chez l'adulte","ok":false,"why":"Les complications pulmonaires sont plus fréquentes chez l'adulte que chez l'enfant, et rares (5 % des cas)."},{"t":"Une pneumopathie favorisée chez l'adulte par le tabagisme et la grossesse","ok":true,"why":"La pneumopathie varicelleuse est favorisée par le tabagisme et la grossesse ; elle est responsable de 30 % des décès de la varicelle de l'adulte."}],"explanation":"Complications : surinfections bactériennes (impétiginisation, fasciite nécrosante, septicémie), pneumopathie varicelleuse, manifestations neurologiques (convulsions hyperthermiques, syndrome de Reye lié à l'aspirine).","src":"p. 229-230"},{"id":"d168-qcm-112","type":"QRM","rank":"A","objective":"d168-obj-15","tags":["traitement","pédiatrie","pièges"],"difficulty":1,"stem":"Une fillette de 5 ans a une varicelle typique, non compliquée. Quelles mesures sont adaptées ?","options":[{"t":"Paracétamol en cas de fièvre","ok":true,"why":"Le paracétamol est l'antipyrétique de la varicelle."},{"t":"Aspirine pour faire baisser la fièvre","ok":false,"why":"L'aspirine expose au syndrome de Reye ; elle est formellement contre-indiquée."},{"t":"Badigeons de chlorhexidine en solution aqueuse","ok":true,"why":"Ils préviennent la surinfection des lésions."},{"t":"Application de talc pour assécher les lésions","ok":false,"why":"Il ne faut pas utiliser de talc."},{"t":"Ongles courts et propres si le prurit est important","ok":true,"why":"Cette mesure prévient les lésions de grattage."}],"explanation":"Varicelle bénigne de l'enfant : pas d'antiviral, éviction de collectivité non obligatoire ; douches quotidiennes tempérées, chlorhexidine aqueuse, ongles courts, paracétamol (ni aspirine ni AINS), antihistaminique anti-H1 sédatif si prurit.","trap":"Aspirine (syndrome de Reye) et AINS (fasciite nécrosante) sont à proscrire dans la varicelle.","src":"p. 237"},{"id":"d168-qcm-113","type":"QRM","rank":"A","objective":"d168-obj-07","tags":["grossesse","pédiatrie"],"difficulty":2,"stem":"À propos de la varicelle chez la femme enceinte et chez son enfant, quelles propositions sont exactes ?","options":[{"t":"Avant la 20e semaine de gestation, il existe un risque de fœtopathie varicelleuse","ok":true,"why":"Le risque de fœtopathie concerne les varicelles survenant avant la 20e semaine."},{"t":"Les antiviraux préviennent de façon prouvée la fœtopathie varicelleuse","ok":false,"why":"L'efficacité préventive des antiviraux n'est pas prouvée (contamination probablement antérieure aux vésicules, traitement trop tardif)."},{"t":"Une varicelle maternelle dans les 5 jours précédant l'accouchement expose à une varicelle néonatale","ok":true,"why":"La fenêtre à risque va de 5 jours avant à 2 jours après l'accouchement."},{"t":"Après la 20e semaine, une varicelle in utero expose à un zona dans les premiers mois de vie","ok":true,"why":"Après la 20e semaine, le risque est celui d'un zona dans les premières semaines ou premiers mois de vie."},{"t":"Un zona chez la femme enceinte n'expose pas l'enfant à un risque de transmission","ok":true,"why":"Le zona maternel n'entraîne pas de risque de transmission."}],"explanation":"Risque fœtal selon le terme : fœtopathie avant la 20e semaine (surtout entre la 13e et la 20e), zona du nourrisson après la 20e, varicelle néonatale grave si la mère est atteinte de 5 jours avant à 2 jours après l'accouchement (aciclovir IV).","src":"p. 231, 237"},{"id":"d168-qcm-114","type":"QRM","rank":"A","objective":"d168-obj-08","tags":["clinique","diagnostic"],"difficulty":2,"stem":"Un homme de 68 ans a des douleurs en brûlure de l'hémithorax droit depuis 3 jours. Ce matin apparaît un placard érythémateux et œdémateux couvert de vésicules groupées en bouquet, disposées en demi-ceinture, sans dépasser la ligne médiane. Quelles propositions sont exactes ?","options":[{"t":"Il s'agit d'un zona intercostal, localisation la plus fréquente","ok":true,"why":"Le zona intercostal ou dorsolombaire représente environ 50 % des cas, avec éruption en demi-ceinture."},{"t":"Il s'agit d'une primo-infection par le VZV","ok":false,"why":"Le zona est une récurrence localisée ; la primo-infection est la varicelle."},{"t":"Les douleurs ont pu précéder l'éruption","ok":true,"why":"Les douleurs radiculaires peuvent précéder l'éruption, l'accompagner ou lui succéder."},{"t":"La sérologie VZV est l'examen de référence pour confirmer le diagnostic","ok":false,"why":"La technique de référence est la PCR VZV sur le liquide d'une vésicule récente ; la sérologie n'a pas d'intérêt pratique."},{"t":"La distribution est radiculaire (métamérique) et unilatérale","ok":true,"why":"Le zona suit un dermatome et reste unilatéral, sauf dans les formes graves."}],"explanation":"Le zona associe des douleurs neuropathiques radiculaires et un placard érythémato-œdémateux couvert de vésicules en bouquet, de distribution radiculaire unilatérale. Les vésicules s'assèchent et croûtent en une dizaine de jours.","src":"p. 231-232, 236"},{"id":"d168-qcm-115","type":"QRM","rank":"A","objective":"d168-obj-13","tags":["complications","clinique"],"difficulty":2,"stem":"Une femme de 72 ans a un zona du territoire du nerf ophtalmique droit avec des vésicules narinaires. Quelles propositions sont exactes ?","options":[{"t":"L'atteinte narinaire fait redouter une atteinte oculaire","ok":true,"why":"L'éruption narinaire et de la cloison traduit l'atteinte du rameau nasal interne et expose à une atteinte oculaire."},{"t":"Les corticoïdes locaux sont indiqués d'emblée","ok":false,"why":"Les corticoïdes locaux sont classiquement contre-indiqués ; ils ne sont indiqués que pour les kératites immunologiques et les uvéites antérieures, après avis ophtalmologique."},{"t":"Un avis ophtalmologique est nécessaire","ok":true,"why":"Une manifestation oculaire relève d'une prise en charge spécialisée (risque de perte fonctionnelle de l'œil)."},{"t":"Après 50 ans, le risque de complications oculaires est plus faible","ok":false,"why":"La fréquence des complications oculaires est accrue après 50 ans."},{"t":"Un traitement antiviral oral est indiqué quel que soit l'âge","ok":true,"why":"Dans le zona ophtalmique, l'antiviral oral est indiqué quel que soit l'âge, pour prévenir les complications oculaires."}],"explanation":"Zona ophtalmique (V1) : antiviral toujours nécessaire, avis ophtalmologique, complications oculaires fréquentes chez le sujet âgé (atteinte cornéenne, uvéite antérieure, kératites stromales et neurotrophiques durables).","src":"p. 233-234, 238-239"},{"id":"d168-qcm-116","type":"QRM","rank":"A","objective":"d168-obj-15","tags":["traitement"],"difficulty":2,"stem":"Parmi ces patients ayant un zona évoluant depuis moins de 72 heures, lesquels relèvent d'un traitement antiviral systémique ?","options":[{"t":"Un homme de 34 ans sans immunodépression, zona thoracique non compliqué","ok":false,"why":"Ni immunodépression, ni âge de 50 ans ou plus, ni zona ophtalmique : pas d'indication. On recherche toutefois une immunodépression chez l'adulte jeune (VIH)."},{"t":"Une femme de 72 ans, zona intercostal","ok":true,"why":"Zona non ophtalmique chez un sujet de plus de 50 ans : antiviral pour prévenir les algies post-zostériennes."},{"t":"Un homme de 45 ans traité par immunosuppresseur, zona thoracique","ok":true,"why":"L'immunodépression est une indication (traitement IV dans ce cas)."},{"t":"Une adolescente de 15 ans immunocompétente, zona de la cuisse sans signe de gravité","ok":false,"why":"Pas d'indication systématique chez le sujet jeune immunocompétent sans zona ophtalmique."},{"t":"Une femme de 30 ans immunocompétente, zona ophtalmique","ok":true,"why":"Le zona ophtalmique est une indication quel que soit l'âge, pour prévenir les complications oculaires."}],"explanation":"Trois indications seulement : sujet immunodéprimé, patient de 50 ans ou plus, zona ophtalmique (territoire du nerf V1). Le traitement doit être commencé au plus tard 72 heures après l'apparition des premières lésions.","src":"p. 238-239"},{"id":"d168-qcm-117","type":"QRM","rank":"A","objective":"d168-obj-09","tags":["complications","traitement"],"difficulty":2,"stem":"À propos des algies post-zostériennes, quelles propositions sont exactes ?","options":[{"t":"Ce sont des douleurs neuropathiques de désafférentation, avec hypoesthésie du territoire atteint","ok":true,"why":"Elles diffèrent des douleurs de la phase initiale du zona."},{"t":"Les antalgiques de palier II à III sont leur traitement de référence","ok":false,"why":"Ces antalgiques sont ceux des douleurs aiguës ; les algies post-zostériennes relèvent d'antalgiques à visée neuropathique (amitriptyline, gabapentine...)."},{"t":"Leur fréquence augmente avec l'âge","ok":true,"why":"Les algies post-zostériennes sont très fréquentes après 50 ans et altèrent la qualité de vie."},{"t":"Une corticothérapie générale est recommandée en phase aiguë pour les prévenir","ok":false,"why":"Il n'y a pas de corticothérapie générale ; la prévention repose sur l'antiviral précoce chez les sujets de plus de 50 ans."},{"t":"Un emplâtre de lidocaïne peut être porté sans limite de durée par jour","ok":false,"why":"L'emplâtre de lidocaïne est limité à 12 heures par jour au maximum."}],"explanation":"Douleurs aiguës du zona : antalgiques de palier II à III, pas de corticothérapie générale. Algies post-zostériennes : amitriptyline ou gabapentine (AMM), carbamazépine ou prégabaline (hors AMM), lidocaïne en emplâtre, capsaïcine locale.","src":"p. 236, 239"},{"id":"d168-qcm-118","type":"QRM","rank":"A","objective":"d168-obj-09","tags":["clinique","complications"],"difficulty":2,"stem":"Une femme de 60 ans a une otalgie très intense avec quelques vésicules de la conque de l'oreille droite, une adénopathie prétragienne et une paralysie faciale. Quelles propositions sont exactes ?","options":[{"t":"Le diagnostic est un zona auriculaire avec réactivation du ganglion géniculé","ok":true,"why":"Le zona auriculaire correspond à la réactivation du virus dans le ganglion géniculé."},{"t":"Les lésions cutanées sont étendues à tout l'hémicorps","ok":false,"why":"Les lésions sont limitées à la zone de Ramsay-Hunt (conduit auditif externe et conque), avec une éruption discrète."},{"t":"Une anesthésie des deux tiers antérieurs de l'hémilangue peut être associée","ok":true,"why":"Elle fait partie du tableau, avec la paralysie faciale éventuelle."},{"t":"Il s'agit de la localisation la plus fréquente du zona","ok":false,"why":"Le zona intercostal ou dorsolombaire est le plus fréquent (environ 50 % des cas)."},{"t":"Des troubles cochléovestibulaires peuvent être associés","ok":true,"why":"Ils peuvent accompagner l'otalgie et la paralysie faciale."}],"explanation":"Zona auriculaire (zone de Ramsay-Hunt) : éruption discrète du conduit auditif externe et de la conque, otalgie très intense, adénopathie prétragienne, anesthésie des deux tiers antérieurs de l'hémilangue, ± paralysie faciale et troubles cochléovestibulaires.","src":"p. 233-234"},{"id":"d168-qcm-119","type":"QRM","rank":"B","objective":"d168-obj-18","tags":["prévention"],"difficulty":2,"stem":"À propos de la vaccination contre la varicelle et contre le zona, quelles propositions sont exactes ?","options":[{"t":"Les vaccins contre la varicelle et contre le zona sont des vaccins à virus vivant atténué","ok":true,"why":"Les deux vaccins sont à virus vivant atténué."},{"t":"Le vaccin contre le zona est recommandé chez les patients immunodéprimés","ok":false,"why":"Il est contre-indiqué chez les personnes immunodéprimées."},{"t":"La vaccination contre la varicelle comporte deux doses espacées d'au moins un mois","ok":true,"why":"Le schéma est de deux doses espacées d'au moins 1 mois, idéalement 3 mois."},{"t":"Le vaccin contre la varicelle est recommandé chez la femme enceinte non immunisée","ok":false,"why":"La vaccination contre la varicelle est contre-indiquée chez la femme enceinte et en cas de déficit immunitaire important."},{"t":"La vaccination contre le zona est recommandée chez les adultes de 65 à 74 ans révolus","ok":true,"why":"Elle est recommandée dans cette tranche d'âge, y compris chez les sujets ayant déjà présenté un zona."}],"explanation":"Varicelle : 2 doses, généralisation non recommandée, indications ciblées (post-exposition, adolescents, femmes en âge de procréer, professionnels de santé...). Zona : une dose, 65 à 74 ans révolus.","src":"p. 237-239"},{"id":"d168-qcm-120","type":"QRM","rank":"B","objective":"d168-obj-02","tags":["épidémiologie"],"difficulty":1,"stem":"À propos de l'épidémiologie de la varicelle et du zona, quelles propositions sont exactes ?","options":[{"t":"La varicelle est la maladie éruptive la plus contagieuse","ok":true,"why":"Elle est décrite comme la maladie éruptive la plus contagieuse ; la séroprévalence dépasse 90 % chez l'adulte."},{"t":"Le zona est fréquent chez l'enfant immunocompétent","ok":false,"why":"Le zona est rare dans l'enfance ; chez l'adulte jeune, il faut rechercher une immunodépression."},{"t":"La varicelle touche surtout les enfants de 1 à 14 ans, avec un pic entre 5 et 9 ans","ok":true,"why":"Plus de 90 % des primo-infections surviennent entre 1 et 14 ans, avec un pic chez l'enfant d'âge scolaire."},{"t":"La varicelle de l'adulte est plus bénigne que celle de l'enfant","ok":false,"why":"Chez l'adulte, le risque de mortalité (pneumopathie) et de formes graves est plus élevé, surtout après 50 ans."},{"t":"Le zona survient surtout après 50 ans","ok":true,"why":"Le zona survient surtout après 50 ans, avec un pic après 75 ans."}],"explanation":"Varicelle : très contagieuse, bénigne chez l'enfant immunocompétent, plus grave chez l'adulte et l'immunodéprimé. Zona : après 50 ans, rare chez l'enfant.","src":"p. 227"},{"id":"d168-qru-101","type":"QRU","rank":"A","objective":"d168-obj-08","tags":["définition","physiopathologie"],"difficulty":1,"stem":"Parmi les propositions suivantes concernant le virus varicelle-zona (VZV), laquelle est exacte ?","options":[{"t":"Le zona est la primo-infection par le VZV, la varicelle en étant la récurrence","ok":false,"why":"C'est l'inverse : la varicelle est la primo-infection et le zona la récurrence."},{"t":"La varicelle est la primo-infection, le zona une récurrence localisée","ok":true,"why":"Même virus à ADN (Herpesviridae) : primo-infection = varicelle ; récurrence localisée = zona."},{"t":"Le VZV est un virus à ARN, contrairement à HSV qui est à ADN","ok":false,"why":"Le VZV est aussi un virus à ADN du groupe des Herpesviridae."},{"t":"La contamination par le VZV peut se faire à partir d'un réservoir animal","ok":false,"why":"La contamination est strictement interhumaine."},{"t":"Après une varicelle, le virus est éliminé et un zona ne peut plus survenir","ok":false,"why":"Le virus reste latent et peut se réactiver : c'est le zona."}],"explanation":"Le VZV est un virus à ADN, de la famille des Herpesviridae, à contamination strictement interhumaine : varicelle (primo-infection) puis zona (récurrence localisée).","src":"p. 226, 240"},{"id":"d168-qru-102","type":"QRU","rank":"A","objective":"d168-obj-15","tags":["complications","traitement"],"difficulty":2,"stem":"Un homme de 34 ans, fumeur, a une varicelle depuis 3 jours. Il présente depuis ce matin une toux, une dyspnée, une fièvre et des hémoptysies ; la radiographie montre des opacités micro- et macronodulaires multiples. Quel traitement antiviral est recommandé ?","options":[{"t":"Valaciclovir per os pendant 7 jours","ok":false,"why":"C'est le schéma du zona du sujet immunocompétent, pas celui d'une varicelle compliquée."},{"t":"Aciclovir par voie IV","ok":true,"why":"Une complication viscérale liée au virus (pneumopathie, hépatite...) est une indication de l'aciclovir IV."},{"t":"Foscarnet par voie IV","ok":false,"why":"Le foscarnet est réservé aux souches résistantes à l'aciclovir."},{"t":"Aucun antiviral, la varicelle de l'adulte guérit spontanément","ok":false,"why":"L'abstention antivirale ne concerne que la varicelle bénigne de l'enfant."},{"t":"Aciclovir en application locale","ok":false,"why":"Les traitements locaux n'ont pas montré d'efficacité."}],"explanation":"Pneumopathie varicelleuse (adulte, tabagisme) : 1 à 6 jours après l'éruption, toux, dyspnée, fièvre, hémoptysies, opacités micro- et macronodulaires ; traitement par aciclovir IV.","src":"p. 229-230, 237"},{"id":"d168-qru-103","type":"QRU","rank":"A","objective":"d168-obj-15","tags":["pédiatrie","traitement","grossesse"],"difficulty":3,"stem":"Une femme accouche à terme. Deux jours plus tard, elle développe une varicelle. Son nouveau-né est asymptomatique, sans éruption. Quelle prise en charge est recommandée pour le nouveau-né ?","options":[{"t":"Surveillance simple, jusqu'à l'apparition éventuelle de vésicules","ok":false,"why":"Le nouveau-né doit être traité avant toute éruption."},{"t":"Aciclovir IV, avant même toute éruption","ok":true,"why":"Indication de l'aciclovir IV : nouveau-né avant toute éruption si la mère a débuté sa varicelle 5 jours avant ou 2 jours après l'accouchement."},{"t":"Aciclovir per os à domicile","ok":false,"why":"La recommandation est l'aciclovir par voie IV."},{"t":"Antibiothérapie anti-staphylococcique préventive","ok":false,"why":"Une antibiothérapie n'est utilisée qu'en cas de surinfection cutanée."},{"t":"Paracétamol et soins locaux seuls","ok":false,"why":"Ces soins symptomatiques sont ceux de la varicelle bénigne de l'enfant, insuffisants pour un nouveau-né exposé."}],"explanation":"La varicelle néonatale est grave (septicémie, atteintes multiviscérales, décès dans 30 % des cas). Le nouveau-né dont la mère débute une varicelle dans la fenêtre de 5 jours avant à 2 jours après l'accouchement reçoit de l'aciclovir IV.","src":"p. 231, 237"},{"id":"d168-qru-104","type":"QRU","rank":"A","objective":"d168-obj-07","tags":["grossesse","complications"],"difficulty":2,"stem":"Une femme enceinte de 16 semaines de gestation développe une varicelle. Quel est le risque principal pour le fœtus ?","options":[{"t":"Une varicelle néonatale avec septicémie et atteintes multiviscérales","ok":false,"why":"Ce risque concerne les varicelles maternelles proches de l'accouchement."},{"t":"Un zona dans les premières semaines ou les premiers mois de vie","ok":false,"why":"Ce risque concerne la varicelle in utero survenant après la 20e semaine."},{"t":"Une fœtopathie varicelleuse (atteintes neurologiques)","ok":true,"why":"Avant la 20e semaine (surtout entre la 13e et la 20e), risque de fœtopathie : atteintes neurologiques, ophtalmologiques, musculo-squelettiques, voire mort in utero."},{"t":"Un herpès néonatal par HSV2","ok":false,"why":"L'herpès néonatal est dû à HSV, pas au VZV."},{"t":"Aucun risque, tant que le terme n'est pas atteint","ok":false,"why":"Il existe un risque fœtal avant la 20e semaine ; une surveillance en centre de diagnostic anténatal est nécessaire."}],"explanation":"Le risque fœtal dépend du terme : fœtopathie avant la 20e semaine, zona du nourrisson après la 20e semaine, varicelle néonatale dans la fenêtre autour de l'accouchement.","src":"p. 231"},{"id":"d168-qru-105","type":"QRU","rank":"A","objective":"d168-obj-08","tags":["diagnostic","pièges"],"difficulty":2,"stem":"Un homme de 28 ans, sans antécédent notable, consulte pour un zona thoracique typique non compliqué. Quelle démarche complémentaire est recommandée ?","options":[{"t":"Une sérologie VZV pour confirmer le diagnostic","ok":false,"why":"La sérologie n'a pas d'intérêt pratique dans le zona."},{"t":"Une biopsie cutanée","ok":false,"why":"La biopsie n'a pas d'intérêt pratique dans le zona."},{"t":"Aucun examen : rechercher une immunodépression n'est pas utile à son âge","ok":false,"why":"Chez l'adulte jeune, on recherche une immunodépression (zona = signal d'alerte)."},{"t":"Une sérologie VIH","ok":true,"why":"Un zona chez l'adulte jeune impose la recherche d'une immunodépression, notamment par la sérologie VIH."},{"t":"Un cytodiagnostic de la lésion","ok":false,"why":"Le cytodiagnostic n'a pas d'intérêt pratique dans le zona."}],"explanation":"Zona chez un adulte jeune : sérologie VIH (et NFS pour une hémopathie de type leucémie lymphoïde chronique si besoin). La PCR VZV est la technique de référence si une confirmation est nécessaire.","src":"p. 236, 240"},{"id":"d168-qru-106","type":"QRU","rank":"A","objective":"d168-obj-15","tags":["traitement"],"difficulty":2,"stem":"Un patient de 55 ans traité par chimiothérapie présente un zona dorsolombaire. Quel est le traitement antiviral à privilégier ?","options":[{"t":"Valaciclovir per os pendant 7 jours","ok":false,"why":"C'est le schéma de l'immunocompétent."},{"t":"Pommade d'aciclovir seule","ok":false,"why":"Les traitements locaux seuls ne sont pas suffisants ; un antiviral systémique est nécessaire."},{"t":"Foscarnet IV","ok":false,"why":"Le foscarnet est réservé aux souches résistantes à l'aciclovir."},{"t":"Aucun antiviral : le zona est bénin à cet âge","ok":false,"why":"L'immunodépression est une indication de l'antiviral et expose à des formes graves."},{"t":"Aciclovir IV, pendant au moins 7 à 10 jours","ok":true,"why":"Chez l'immunodéprimé, l'antiviral est administré par voie IV, avec une durée minimale de 7 à 10 jours (AMM)."}],"explanation":"Zona de l'immunodéprimé : aciclovir IV (au moins 7 à 10 jours). L'arrêt du traitement immunosuppresseur, y compris la corticothérapie, n'est pas systématique.","src":"p. 239"},{"id":"d168-qru-107","type":"QRU","rank":"A","objective":"d168-obj-11","tags":["traitement","urgence"],"difficulty":2,"stem":"Une femme de 25 ans a une primo-infection herpétique génitale avec des douleurs intenses et une rétention d'urines. Quelle prise en charge est adaptée ?","options":[{"t":"Valaciclovir per os en ambulatoire, sans autre mesure","ok":false,"why":"Une forme sévère compliquée (rétention d'urines, douleurs intenses) relève de l'aciclovir IV."},{"t":"Crème antivirale locale et surveillance","ok":false,"why":"Les traitements locaux n'ont pas montré d'efficacité."},{"t":"Abstention thérapeutique, car l'évolution est favorable en 2 à 3 semaines","ok":false,"why":"Cette évolution spontanée ne dispense pas du traitement antiviral ni de la prise en charge de la douleur."},{"t":"Aciclovir IV avec sondage urinaire et antalgiques","ok":true,"why":"Forme sévère compliquée : aciclovir IV, sondage urinaire et antalgiques, avec dépistage des IST."},{"t":"Antalgiques seuls, sans antiviral","ok":false,"why":"Les antalgiques sont une mesure associée ; l'antiviral reste indiqué."}],"explanation":"Primo-infection génitale : aciclovir ou valaciclovir PO dans les formes simples ; aciclovir IV dans les formes sévères compliquées (rétention d'urines, douleurs intenses, terrain fragile), avec sondage urinaire, antalgiques, dépistage des IST et soutien.","src":"p. 216, 225"},{"id":"d168-qru-108","type":"QRU","rank":"A","objective":"d168-obj-14","tags":["diagnostic","paraclinique"],"difficulty":2,"stem":"Une patiente de 30 ans présente des ulcérations génitales récidivantes d'aspect atypique. Quel examen permet de confirmer le diagnostic d'herpès ?","options":[{"t":"Une sérologie HSV (IgG) sur un seul prélèvement","ok":false,"why":"Les IgG sont positives chez 80 % des adultes : cette sérologie ne prouve pas l'origine des lésions."},{"t":"Une culture virale en première intention","ok":false,"why":"La PCR a remplacé la culture."},{"t":"Aucun examen : le diagnostic est toujours clinique","ok":false,"why":"Une forme atypique justifie une confirmation virologique."},{"t":"Une biopsie cutanée avec examen anatomopathologique","ok":false,"why":"La confirmation repose sur la PCR d'un prélèvement de la lésion."},{"t":"Une PCR HSV sur un prélèvement de la lésion","ok":true,"why":"La PCR est la technique de référence, très sensible et très spécifique, avec résultat en moins de 24 heures."}],"explanation":"En cas d'atypie, de gravité ou de contexte à risque, un diagnostic virologique est demandé : PCR sur prélèvement de la lésion récente.","src":"p. 223-224, 226"}],"edn":[],"trees":[],"treatments":{"data":[],"strategies":[]},"cases":[],"ecg":{"data":[],"method":""},"echo":{"data":[]},"flash":null,"pareto":{"id":"d168-pareto","points":[{"id":"d168-par-01","rank":"A","cat":"traitement","text":"Zona : antiviral (**valaciclovir PO 7 j**) si **≥ 50 ans**, **immunodépression** ou **zona ophtalmique**, à débuter dans les **72 h** ; immunodéprimé : **aciclovir IV** ; pas de corticoïdes généraux","src":"p. 238-239"},{"id":"d168-par-02","rank":"A","cat":"piège","text":"Varicelle bénigne de l'enfant : **paracétamol**, **jamais d'aspirine** (Reye) ni d'**AINS** (fasciite nécrosante) ; **pas d'antiviral**, éviction non obligatoire ; chlorhexidine aqueuse, pas de talc","src":"p. 230, 237"},{"id":"d168-par-03","rank":"A","cat":"gravité","text":"Herpès graves : **Kaposi-Juliusberg** (sur dermatite atopique), herpès **néonatal**, atteinte **cornéenne** (avis ophtalmo, pas de corticoïdes locaux), méningo-encéphalite → antiviral **IV**","src":"p. 217-218, 222"},{"id":"d168-par-04","rank":"A","cat":"clinique","text":"**Zona** : douleurs radiculaires **neuropathiques** + vésicules en bouquet **unilatérales métamériques** ; **intercostal 50 %** ; V1 avec **éruption narinaire** = risque oculaire → avis ophtalmo","src":"p. 231-233"},{"id":"d168-par-05","rank":"A","cat":"examen","text":"Herpès : diagnostic **clinique** si forme typique sans terrain à risque ; sinon **PCR** sur lésion récente (référence, a remplacé la culture) ; **sérologie inutile** (IgG + chez 80 % des adultes)","src":"p. 223-224"},{"id":"d168-par-06","rank":"A","cat":"traitement","text":"HSV : **aciclovir** (inhibe l'**ADN polymérase** virale) ou **valaciclovir** PO ; **IV** si forme sévère ; **foscarnet** si résistance ; **traitements locaux inefficaces**","src":"p. 224-225"},{"id":"d168-par-07","rank":"A","cat":"gravité","text":"Varicelle compliquée : surinfection (**staphylocoque, streptocoque**), **fasciite nécrosante** (urgence), **pneumopathie** de l'adulte (tabac, grossesse), immunodéprimé → **aciclovir IV**","src":"p. 229-231, 237"},{"id":"d168-par-08","rank":"A","cat":"gravité","text":"Varicelle et grossesse : avant **20 SG** → **fœtopathie** ; de **5 j avant à 2 j après** l'accouchement → varicelle **néonatale** grave (aciclovir IV) ; après 20 SG : zona du nourrisson","src":"p. 231, 237"},{"id":"d168-par-09","rank":"A","cat":"clinique","text":"**Herpès récurrent** : **prodromes** stéréotypés (dysesthésie cuisante, picotements) → **vésicules en bouquet** → érosions, croûtes ; cicatrisation 7-14 j ; siège stéréotypé, **labial** le plus fréquent","src":"p. 219"},{"id":"d168-par-10","rank":"A","cat":"traitement","text":"Prévention de l'herpès : **> 6 récurrences/an** → aciclovir ou valaciclovir PO **6-12 mois** puis réévaluation ; récurrence orofaciale banale : **pas d'antiviral**","src":"p. 224-225"},{"id":"d168-par-11","rank":"A","cat":"clinique","text":"**Varicelle** : incubation **14 j**, éruption **descendante** (cuir chevelu) de **vésicules ombiliquées** d'âges différents, prurit intense, érosions muqueuses ; guérison rapide chez l'enfant","src":"p. 228, 240"},{"id":"d168-par-12","rank":"A","cat":"définition","text":"**VZV** : varicelle = **primo-infection**, zona = **récurrence** localisée. **HSV** : primo-infection (80 % asymptomatique) → latence en **ganglion sensitif** → récurrences","src":"p. 211-212, 226"},{"id":"d168-par-13","rank":"A","cat":"gravité","text":"Herpès génital : primo-infection = **vulvovaginite** fébrile très douloureuse, **rétention d'urines** = gravité ; **lésions au travail → césarienne** ; primo-infection de la femme enceinte : hépatite fulminante","src":"p. 215-216, 218, 225"},{"id":"d168-par-14","rank":"A","cat":"examen","text":"Zona : **PCR VZV** sur vésicule récente (référence) ; **adulte jeune → sérologie VIH** (+ NFS) ; diagnostics différentiels : érysipèle de la face, impétigo, HSV, eczéma","src":"p. 236, 240"},{"id":"d168-par-15","rank":"A","cat":"traitement","text":"Douleurs du zona : antalgiques **II-III** en phase aiguë ; **algies post-zostériennes** (fréquentes après 50 ans) → **amitriptyline** ou **gabapentine**, emplâtre de lidocaïne (12 h/j max)","src":"p. 236, 239"}]},"extra":{"semio":[],"criteres":[],"chiffres":[],"physio":[],"parcours":[],"examens":[]}});
